Here's a Python program to find the maximum possible time and the initial permutation:

```python
import math

def max_worst_case(n):
    permutations = []
    for i in range(n, 0, -1):
        permutations.append(range(1, i+1))

    max_time = 0
    best_permutation = None
    best_operations = None

    for perm in permutations:
        operations = 0
        for i in range(1, n-1):
            if perm[i-1] != i or perm[i+1] != i:
                operations += (i - perm[i])**2

        if operations > max_time:
            max_time = operations
            best_permutation = perm
            best_operations = 1

        for i in range(n-2):
            if operations == (n-1-i)/2:
                for j in range(n-1-i):
                    if best_permutation[i+j] != best_permutation[i+j+1]:
                        operations += (i + j + 1)**2
                if operations > max_time:
                    max_time = operations
                    best_permutation = perm
                    best_operations = (n-1-i)//2 + 1

                for j in range(n-1-i, n-1):
                    if best_permutation[i+j] != best_permutation[i+j+1]:
                        operations += (i + j + 1)**2
                    if operations > max_time:
                        max_time = operations
                        best_permutation = perm
                        best_operations = n - 1 - i

        for start in range(1, math.ceil((n-1)/2)):
            end = n - start
            if best_permutation[start-1] != best_permutation[end-1]:
                    operations += (start * end)**2
            if operations > max_time:
                max_time = operations
                best_permutation = perm
                best_operations = end - start

    return max_time, best_permutation, best_operations

