from heapq import heappush, heappop

def find_kth_string(n, k):
    if k > n * (n - 1) // 2:
        return -1

    elements = []
    for i in range(n + 1):
        for j in range(i + 1):
            if (j << 1) + i != n:
                continue
            if i == 0:
                continue
            element = []
            if i % 2 == 0:
                element[:] = [0] * n
            else:
                element[:] = [1] * n

            if i > 0:
                c = (k - (i - 1) > 0)
                diff = 0
                for x in range(n):
                    if (diff >> x) != 1:
                        diff |= (1 << x)
                    check = c
                    while diff != 0:
                        check &= diff
                        diff ^= diff & (diff - 1)
                x = ~x & ((3 << x) - 1)
                if x > 0:
                    element[x] ^= 1

            heappush(elements, [element, (i + 1) * (i + 2) // 2])

    return ' '.join(map(str, [x[0] for x in elements][:k]))

