def min_cost_to_win(n, strengths):
    if n == 2:
        if strengths[1] == -1:
            return 0
        else:
            return int(math.log2(strengths[1]))  # Based on binary log
    costs = [sys.maxsize] * (n + 1)
    costs[1] = strengths[1]

    for i in range(2, n + 1):
        for j in range(i // 2, 0, -1):
            op_1, op_2 = strengths[i], strengths[j]
            opp_1, opp_2 = strengths[2 * i], strengths[2 * i + 1]

            if j == n // 2:
                cost = min(op_1, op_2) + 2
            else:
                cost = -min(op_1, op_2) + (n // 2 - j + 1)

            if i // 2 == j:
                cost += max(op_1, opp_2)  # Bribe boxer j if i is paired with j
            elif i % j == 1:
                cost += max(op_1, opp_1)  # Bribe boxer j if i overlaps with j
            else:
                cost += max(opp_1, opp_2)

            costs[i] = min(costs[i - 1], cost)

    return costs[n]

